/**
 * Photographs embedded as data URIs.
 *
 * WHY NOT FILES. A normal `require("../assets/x.jpg")` becomes an Android
 * drawable resource at BUILD time, and Gradle cannot run from this machine's
 * agent shell - its launcher can never open a socket to its daemon. Data URIs
 * live inside the JS bundle instead, so an image can be added or changed and
 * reinstalled in about three minutes with no native build at all.
 *
 * The cost is bundle size, so each one is cropped to the size it is actually
 * drawn at and compressed hard. Do not paste a full-resolution photograph in
 * here - regenerate with the script in the commit that added this file.
 *
 * Provenance, because a government-facing tool should account for every asset
 * it ships:
 *   FIELD       Pexels 17971746  - Pexels licence, free commercial, no mark
 *   EXCAVATOR   Pixabay 2781679  - Pixabay licence, free commercial, no mark
 *   UNDERGROUND, RAILS, SEAM - supplied by the team, no watermark or third
 *   party logo present. Origin unconfirmed; replace with a Pexels/Unsplash
 *   equivalent before any public release.
 *
 * Deliberately NOT here: the Ministry of Coal / State Emblem artwork. Its use
 * is restricted by the State Emblem of India (Prohibition of Improper Use)
 * Act 2005, and a prototype asserting government authority it does not have
 * is the one image mistake this project cannot afford.
 */

export const FIELD_PHOTO = "data:image/jpeg;base64,";

export const EXCAVATOR_PHOTO = "data:image/jpeg;base64,";

export const UNDERGROUND_PHOTO = "data:image/jpeg;base64,";

export const RAILS_PHOTO = "data:image/jpeg;base64,";

export const SEAM_PHOTO = "data:image/jpeg;base64,";
